        "line": "p1:L21"
      },
      {
        "group": "환경",
        "class_code": "ENV_AQ_CHRONIC",
        "category": "1",
        "raw": "수생 환경유해성(만성) : 구분 1",
        "line": "p1:L22"
      }
    ],
    "signal_word": "경고",
    "pictograms": [
      {
        "code": "GHS07"
      },
      {
        "code": "GHS09"
      }
    ],
    "h_statements": [
      {
        "code": "H317",
        "text": "알레르기성 피부 반응을 일으킬 수 있음.",
        "line": "p1:L28"
      },
      {
        "code": "H400",
        "text": "수생생물에 매우 유독함.",
        "line": "p1:L29"
      },
      {
        "code": "H410",
        "text": "장기적인 영향에 의해 수생생물에게 매우 유독함.",
        "line": "p1:L30"
      }
    ],
    "p_statements": [
      {
        "code": "P101",
        "type": "일반",
        "text": "의학적인 조치가 필요한 경우, 제품의 용기 또는 라벨을 보시오.",
        "line": "p1:L32"
      },
      {
        "code": "P102",
        "type": "일반",
        "text": "어린이 손이 닿지 않는 곳에 보관하시오.",
        "line": "p1:L33"
      },
      {
        "code": "P103",
        "type": "일반",
        "text": "사용 전에 라벨을 읽으시오.",
        "line": "p1:L34"
      },
      {
        "code": "P261",
        "type": "예방",
        "text": "분진/미스트의 흡입을 피하시오.",
        "line": "p1:L35"
      },
      {
        "code": "P272",
        "type": "예방",
        "text": "작업장 밖으로 오염된 작업복을 반출하지 마시오.",
        "line": "p1:L36"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑을 착용하시오.",
        "line": "p1:L38"
      },
      {
        "code": "P273",
        "type": "예방",
        "text": "환경으로 배출하지 마시오.",
        "line": "p1:L39"
      },
      {
        "code": "P302+P352",
        "type": "대응",
        "text": "피부에 묻으면: 다량의 물과 비누로 씻으시오.",
        "line": "p1:L40"
      },
      {
        "code": "P333+P313",
        "type": "대응",
        "text": "피부자극 또는 홍반이 나타나면; 의학적인 조치을 받으시오.",
        "line": "p1:L41"
      },
      {
        "code": "P321",
        "type": "대응",
        "text": "적절한 처치를 하시오.（「4. 응급조치 요령」를 참조）",
        "line": "p1:L42"
      },
      {
        "code": "P362+P364",
        "type": "대응",
        "text": "오염된 의류를 벗고 다시 사용 전 세척하시오.",
        "line": "p1:L43"
      },
      {
        "code": "P391",
        "type": "대응",
        "text": "누출물을 모으시오.",
        "line": "p1:L44"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "폐기물 관련 법령에 따라 내용물/용기를 폐기하시오.",
        "line": "p1:L46"
      }
    ],
    "other_hazards": [
      {
        "value": "분진폭발 위험성",
        "line": "p1:L47"
      }
    ],
    "lines": {
      "classified": "p1:L19",
      "signal_word": "p1:L26",
      "pictograms": "p1:L24"
    }
  },
  "narratives": [],
  "extras": []
}

